// Converte o lead do Meta (Facebook/Instagram) para o formato do CRM
const j = $input.first().json;
// O formato varia conforme a versão do nó: aceita "data" (simplificado) ou "field_data" (bruto)
let fields = j.data || {};
if (Array.isArray(j.field_data)) {
  fields = Object.fromEntries(j.field_data.map(f => [f.name, (f.values || [])[0]]));
}
const get = (...keys) => keys.map(k => fields[k]).find(v => v !== undefined && v !== '') ?? null;

// Perguntas personalizadas do formulário viram "interesse"
const padrao = ['full_name', 'first_name', 'last_name', 'phone_number', 'email'];
const extras = Object.entries(fields)
  .filter(([k]) => !padrao.includes(k))
  .map(([k, v]) => `${k.replace(/_/g, ' ')}: ${v}`)
  .join(' | ');

const platform = String(j.platform || j.data?.platform || '').toLowerCase();
return [{ json: {
  name: get('full_name') || [get('first_name'), get('last_name')].filter(Boolean).join(' ') || 'Lead Meta',
  phone: get('phone_number', 'telefone', 'whatsapp'),
  email: get('email'),
  source: platform === 'ig' || platform === 'instagram' ? 'INSTAGRAM' : 'META_ADS',
  externalId: String(j.id || j.leadgen_id || ''),
  campaign: j.campaign?.name || j.campaign_name || j.form?.name || null,
  interest: extras || null,
  raw: j,
} }];
